window.LD=window.LD||{};window.LD["party/p2"]={"id":"p2","name":"The Vigil of Carrbridge","poss":"The Vigil of Carrbridge's","members":["h10","h1"],"leader":"h10","morale":100,"disposition":"honorable","motto":"Our word holds longer than your wall.","banner":{"c1":"#e8e8e8","c2":"#d860a8","emblem":"star"},"loc":"bleakmarsh","loc_name":"Bleakmarsh","goal":{"text":"to finish the season as one of the top three parties","kind":"top","done":90,"progress":"currently 1st","missed":false,"crew":"The Vigil of Carrbridge","party":"p2"},"vows":[{"text":"to keep the peace: never draw first on another hero","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Vigil of Carrbridge","party":"p2"}],"doing":"last seen hunting in Bleakmarsh","progress":null,"today":["Hunted all day without turning up a fight.","XP: Juniper +871 (level 20!), Brix +876 (level 20!).","Foraged 3 herbs, a sprig of moonpetal.","Came away with a fish.","Ate 2 rations."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"dear_yeti_society","title":"Dear Yeti Society","tone":"funny","meter":"4/4","bpm":112,"diff":4,"day":47,"night":"n116","n":13,"by":null,"lead":{"id":"h10","name":"Juniper","skill":0.811,"inst":"lute"}},"renown":295,"season":{"wins":5,"bosses":1,"floors":3,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30},"career":{"wins":17,"bosses":1,"floors":11,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"donkey_cart","name":"Grand Duchess","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":61,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"donkey","name":"Mabel","label":"donkey","colour":"grey","owner":null},"paid":[["Brix",20],["Juniper",9]]},"pace_gap":0,"rels":[{"party":"p4","score":100},{"party":"p1","score":54},{"party":"p8","score":28},{"party":"p6","score":25},{"party":"p3","score":4}],"events":[{"id":"e27","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Juniper and Brix shake on it at The Honest Toll: they are now The Vigil of Carrbridge. (Honorable, by the look of them.)","heroes":["h10","h1"],"parties":["p2"],"loc":"carrbridge","wx":"storm"},{"id":"e518","day":14,"season":1,"sday":14,"kind":"road","imp":4,"text":"There is a road where there was a field yesterday. It runs due west and has milestones that count backwards. Brix walks it, and arrives somewhere known and strange.","heroes":["h1","h10"],"parties":["p2"],"road":"ashveil_crypts~hollowood","road_rec":"r125"},{"id":"e761","day":20,"season":1,"sday":20,"kind":"gear","imp":1,"text":"In the chantry on the first floor of the Ashveil Crypts, Juniper finds a Grave-Blessed Ranger's Hood and puts it on. Grave-Blessed: much braver (+7 nerve).","heroes":["h10"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e762","day":20,"season":1,"sday":20,"kind":"delve_day","imp":1,"text":"The Vigil of Carrbridge spends the day on the first floor of the Ashveil Crypts, with a look round every corner, and covers three rooms: the bearers' ramp, sloped for coffins, the grave-goods store, the chantry.","heroes":["h10","h1"],"parties":["p2"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":3,"empty":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":0,"wild":[]}},{"id":"e763","day":20,"season":1,"sday":20,"kind":"delve_done","imp":1,"text":"Up the last steps after 4 days: The Vigil of Carrbridge climbs into the sun and nobody says anything for a while. They got down to the first floor, mapped 33% of it, came across the chantry, worked through 4 rooms, split 58 silver on the way up and turned back because they were down to the last torch. Counting every crew that has been down, the Ashveil Crypts is partly explored (43%).","heroes":["h10","h1"],"parties":["p2"],"loc":"ashveil_crypts","days":4,"bottom":false,"rooms":["the chantry"],"gold":58,"turn":"dark"},{"id":"e823","day":21,"season":1,"sday":21,"kind":"ledger","imp":2,"text":"MARKET WEEK: 15 hauls sold across the realm, 912 silver all told. Biggest haul: Barnaby, 152 silver in Ironhaven. Back up from the deep: The Vigil of Carrbridge (4 days in the Ashveil Crypts).","heroes":["h19","h10"],"parties":["p2"]},{"id":"e825","day":21,"season":1,"sday":21,"kind":"big_move","imp":4,"text":"Nhalkral Who Eats Bells is dead! It falls to Brix, Juniper in the Ashveil Crypts. On the table: Juniper +103 renown (5th to 1st) and Brix +73 (6th to 2nd). The Vigil of Carrbridge +88 party renown (4th to 2nd among the crews).","heroes":["h10","h1"],"parties":["p2"],"cause":"e790","moves":[{"hero":"h10","gain":103,"from":5,"to":1},{"hero":"h1","gain":73,"from":6,"to":2}],"party_moves":[{"party":"p2","gain":88,"from":4,"to":2}],"fight":"f55"},{"id":"e850","day":22,"season":1,"sday":22,"kind":"road","imp":3,"text":"Captain Mabb challenges Brix to a race to the next town for bragging rights. Brix wins by a mile. The mule wins the sulk.","heroes":["h1","h10"],"parties":["p2"],"road":"ashfen~carrbridge","traveller":"fourth_best","road_rec":"r202"},{"id":"e860","day":22,"season":1,"sday":22,"kind":"campfire","imp":1,"text":"Brix talks Juniper through a bad night about the dark. Neither mentions it in the morning. Both remember.","heroes":["h1","h10"],"parties":["p2"],"loc":"ashfen","wx":"fog"},{"id":"e869","day":23,"season":1,"sday":23,"kind":"road","imp":3,"text":"Master Vellum takes notes on Brix in a little book. 'Very dramatic,' says the old actor. 'Could use a hat.'","heroes":["h1","h10"],"parties":["p2"],"road":"ashfen~carrbridge","traveller":"gilded_thimble","road_rec":"r207"},{"id":"e900","day":23,"season":1,"sday":23,"kind":"ability","imp":2,"text":"A Carrbridge family asks Juniper to say the words at Grandad's wake. She makes everyone laugh twice. 24 silver and a ration of funeral ham.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"weddings_and_wakes","sk":"Weddings and Wakes","rule":true},{"id":"e929","day":24,"season":1,"sday":24,"kind":"boss_race","imp":2,"text":"The Vigil of Carrbridge leaves Vessimir the Unburied to Red Hammers and The Amber Sigil: they have turned for the Sunken Vault and The Kraken of the Vault instead.","heroes":["h10","h1"],"parties":["p2"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e951","day":25,"season":1,"sday":25,"kind":"road","imp":3,"text":"Juniper is called to attention by Sergeant Hobb Withy for a quick inspection of kit. The kit passes, and so, grudgingly, does the hero.","heroes":["h10","h1"],"parties":["p2"],"road":"carrbridge~saltmarrow","traveller":"withy","road_rec":"r224"},{"id":"e967","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Brix casts a line from every bridge on the route. At the fourth, a pike. Brix names it. That's Angler for you.","heroes":["h1"],"parties":["p2"],"loc":"carrbridge","skill":"angler"},{"id":"e968","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Juniper checks the stores at midday and adjusts the plan: half rations tonight, a feast tomorrow. It works. Somebody asks how. 'Supply Master,' says Juniper.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"supply_master"},{"id":"e993","day":26,"season":1,"sday":26,"kind":"road","imp":2,"text":"A small chest sits in a ditch off the road to Saltmarrow with the key tied to the handle on a string. Brix turns the key and finds a few bright things and a dried flower, left like a joke.","heroes":["h1","h10"],"parties":["p2"],"road":"carrbridge~saltmarrow","road_rec":"r230"},{"id":"e1079","day":28,"season":1,"sday":28,"kind":"tarot","imp":2,"text":"Juniper lays three cards on a flat stone for The Vigil of Carrbridge, with the Sunken Vault a short walk off in the dark: the Chariot, the King of Wands and the King of Pentacles upside down. Juniper says it could go either way.","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault","reading":"r242"},{"id":"e1106","day":29,"season":1,"sday":29,"kind":"delve","imp":1,"text":"The Vigil of Carrbridge descends into the Sunken Vault, untouched (0%).","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e1107","day":29,"season":1,"sday":29,"kind":"fight","imp":2,"text":"It's 2 Cliff Crabs and the Drowned against the Vigil of Carrbridge in the barnacled quay steps on the first floor of the Sunken Vault, and it isn't close. The last cliff crab looks at the odds and leaves. Brix waited for the gap and put Headshot through it. Loot: 4 remains, 5 barnacle oysters, 2 chitin.","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault","fight":"f72","foes":["drowned","crab","crab"],"where":"in the barnacled quay steps on the first floor of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-48},{"id":"e1108","day":29,"season":1,"sday":29,"kind":"trap","imp":1,"text":"Brix springs a tripwire in the gate passage on the first floor of the Sunken Vault (concussion).","heroes":["h1"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e1109","day":29,"season":1,"sday":29,"kind":"delve_day","imp":1,"text":"By lamplight on the first floor of the Sunken Vault, The Vigil of Carrbridge clears the way through three rooms, without stopping for side rooms: the tide-gate, the barnacled quay steps, the gate passage.","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault","pace":"push","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":1,"sprung":1,"trap_inj":1,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1110","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Brix drills Juniper on the parry for an hour. Juniper's parry is now a real parry. Fencing Lessons, minus the shouting.","heroes":["h1","h10"],"parties":["p2"],"loc":"sunken_vault","skill":"fencing_lessons"},{"id":"e1140","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"The map of the Sunken Vault grows by one room of the first floor, walked without hurrying by The Vigil of Carrbridge: the tide-gate.","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1142","day":30,"season":1,"sday":30,"kind":"night","imp":1,"text":"A woman with a lantern and no luggage walks into The Vigil of Carrbridge's camp on the first floor of the Sunken Vault, asks the way to the Ashveil Crypts, and leaves the firelight in the wrong direction.","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e1175","day":30,"season":1,"sday":30,"kind":"delve_done","imp":1,"text":"The daylight is a shock after 2 days, and The Vigil of Carrbridge comes out into it shading every eye. They worked through 4 rooms and got down to the first floor.","heroes":["h10","h1"],"parties":["p2"],"loc":"sunken_vault","days":2,"bottom":false,"rooms":[],"gold":0},{"id":"e1179","day":30,"season":1,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Vigil of Carrbridge set out to finish the season as one of the top three parties, and the final table says they made it. XP: Juniper +800, Brix +800.","heroes":[],"parties":["p2"],"xp":{"h10":800,"h1":800}},{"id":"e1210","day":31,"season":2,"sday":1,"kind":"map_bought","imp":2,"text":"The Vigil of Carrbridge buys a map of Thornmere Ruins in Thornwall for 42 silver, drawn by Gorm. The place is partly explored (40%).","heroes":["h10","h1","h9"],"parties":["p2"],"loc":"thornwall"},{"id":"e1225","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"A race for Mother Thornmere: The Vigil of Carrbridge and The Sunlit Almanac are all bound for Thornmere Ruins. Only one of them gets the kill.","heroes":["h10","h1","h8","h20","h18","h19"],"parties":["p2","p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1230","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Juniper blesses a new mill in Carrbridge, a goat and a very nervous baby, all before lunch. 34 silver, and a ration for the road.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"weddings_and_wakes","sk":"Weddings and Wakes","rule":true},{"id":"e1237","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Thirty days in The Vigil of Carrbridge. Juniper and Brix have stopped keeping score of who owes whom.","heroes":["h10","h1"],"parties":["p2"],"loc":"carrbridge"},{"id":"e1248","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Vigil of Carrbridge stands before the league and swears it: to keep the peace: never draw first on another hero. The Annals are watching.","heroes":["h10","h1"],"parties":["p2"]},{"id":"e1264","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Juniper practises a wedding speech on the party. Brix cries at the bit about the goat. Juniper puts it down to Weddings and Wakes.","heroes":["h10","h1"],"parties":["p2"],"loc":"bleakmarsh","skill":"weddings_and_wakes","wx":"fog"},{"id":"e1273","day":32,"season":2,"sday":2,"kind":"meet","imp":1,"text":"The Vigil of Carrbridge and The Sunlit Almanac share a fire in Bleakmarsh. There is a short argument about the best road to Carrbridge.","heroes":["h10","h1","h8","h20","h18","h19"],"parties":["p2","p4"],"loc":"bleakmarsh","wx":"fog"},{"id":"e1277","day":32,"season":2,"sday":2,"kind":"journey","imp":2,"text":"The Sunlit Almanac and The Vigil of Carrbridge walk to Bleakmarsh together. Someone brings up Isolde's terrible singing. Someone always does.","heroes":["h8","h20","h18","h19","h10","h1"],"parties":["p4","p2"]},{"id":"e1286","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Brix lets Juniper pick the target: a knot on a far pine. Dead centre. Juniper picks a harder one. Chalk it up to Follow My Arrow.","heroes":["h1","h10"],"parties":["p2"],"loc":"bleakmarsh","skill":"follow_my_arrow","wx":"fog"},{"id":"e1298","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Juniper sings an evening hymn by the fire. Even Brix, a sceptic, hums the last line.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","skill":"hymn_singer","wx":"fog"},{"id":"e1299","day":33,"season":2,"sday":3,"kind":"night","imp":2,"text":"Something small and clever gets into The Vigil of Carrbridge's camp in Thornmere Ruins overnight. Brix wakes up 10 silver and 2 rations lighter.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1310","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Brix puts an arrow into a crack in the wall. 'Lever's there.' It is. That's Follow My Arrow for you.","heroes":["h1"],"parties":["p2"],"loc":"thornmere_ruins","skill":"follow_my_arrow","wx":"fog"},{"id":"e1344","day":34,"season":2,"sday":4,"kind":"delve","imp":1,"text":"The Vigil of Carrbridge descends into Thornmere Ruins, partly explored (45%), map in hand.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1345","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"A long day on the second floor of Thornmere Ruins. The Vigil of Carrbridge comes through four rooms, at a steady pace: the illuminators' desks, the eel-traps, the sacristy and 1 more.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"empty":4,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1364","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"Chalk marks on three rooms of the deepest floor of Thornmere Ruins say The Vigil of Carrbridge has been through, at a hard pace (the black pool, the cloister walk, the abbot's lodging).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"empty":1,"size":2,"floor":3,"traps":1,"sprung":1,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1389","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"Juniper and Brix find a pear tree by the road and eat far more than is wise.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1398","day":36,"season":2,"sday":6,"kind":"trap","imp":2,"text":"Juniper springs a rolling stone in the wellhead on the deepest floor of Thornmere Ruins (cracked collarbone) (Brix hurt too).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1399","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Vigil of Carrbridge pushes on through the deepest floor of Thornmere Ruins one door at a time. Four rooms by nightfall: the chandlery, the dormitory, the lamp-lit passage and 1 more.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"empty":2,"size":2,"floor":3,"traps":1,"sprung":1,"trap_inj":2,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1437","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Vigil of Carrbridge keeps at the deepest floor of Thornmere Ruins at full stretch, five rooms deep in the day: the chapel of the first abbot, the undercroft arches, a hidden room behind the undercroft arches and 2 more.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":5,"empty":4,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1446","day":37,"season":2,"sday":7,"kind":"sniped","imp":3,"text":"Mother Thornmere was killed by The Sunlit Almanac today, and The Vigil of Carrbridge and The Oath of Frosthold all hear it from the same tired messenger. Their trips are rethought on the spot.","heroes":["h1","h10","h18","h19","h20","h3","h7","h8"],"parties":["p2","p4","p7"],"loc":"thornmere_ruins","snipers":["h8","h20","h18","h19"],"where":"many","boss":"Mother Thornmere","in_fight":"f91"},{"id":"e1489","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"Torch by torch through the deepest floor of Thornmere Ruins, The Vigil of Carrbridge makes it through two rooms, with a look round every corner: the brewhouse, the choir loft.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":1,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1532","day":39,"season":2,"sday":9,"kind":"party_life","imp":3,"text":"Juniper, reigning Hero of the Season, sat down on the third floor with the calm of somebody who has made a decision. Nobody could unmake it, and The Vigil of Carrbridge turns for the surface.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","refusal":"h10"},{"id":"e1533","day":39,"season":2,"sday":9,"kind":"delve_done","imp":3,"text":"Up the last steps after 6 days: The Vigil of Carrbridge climbs into the sun and nobody says anything for a while. They worked through 6 rooms, got all the way to the bottom, inked 75% of the map, came across the lamp-lit passage, the ossuary and the brewhouse, split 104 silver on the way up and turned back when one of them would go no further. The Sunlit Almanac got the boss. The Vigil of Carrbridge got the rest. Thornmere Ruins now stands mostly explored (69%), every crew's chalk marks counted.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","days":6,"bottom":true,"rooms":["the lamp-lit passage","the ossuary"],"gold":104,"turn":"refused"},{"id":"e1551","day":39,"season":2,"sday":9,"kind":"campfire","imp":2,"text":"Brix aims an arrow at a far-off crow, misses on purpose, and gets a laugh out of Juniper.","heroes":["h1","h10"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e1589","day":40,"season":2,"sday":10,"kind":"map_shared","imp":1,"text":"The Vigil of Carrbridge draws Gilded Wall a rough copy of Thornmere Ruins on the back of a ration wrapper, as far as the deepest floor. Friends do that.","heroes":["h10","h1","h9","h6"],"parties":["p2","p6"],"loc":"bleakmarsh","dungeon":"thornmere_ruins","price":0},{"id":"e1590","day":40,"season":2,"sday":10,"kind":"meet","imp":2,"text":"Gilded Wall and The Vigil of Carrbridge pass on the road between Bleakmarsh and Thornmere Ruins and split the last of somebody's bread. The news goes round twice.","heroes":["h9","h6","h10","h1"],"parties":["p6","p2"],"loc":"bleakmarsh"},{"id":"e1595","day":40,"season":2,"sday":10,"kind":"campfire","imp":1,"text":"Brix builds Juniper a small brass gadget that mostly works. Juniper keeps it anyway.","heroes":["h1","h10"],"parties":["p2"],"loc":"bleakmarsh"},{"id":"e1649","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Vigil of Carrbridge's plan for the season, as told to the barkeep: to see the world: 6 different places before the season ends.","heroes":["h10","h1"],"parties":["p2"]},{"id":"e1675","day":42,"season":2,"sday":12,"kind":"road","imp":4,"text":"A silent old champion plays chess at a milestone on the road to Carrbridge against anyone who stops. Juniper sits down, plays the game of her life, and is told it was a good one.","heroes":["h10","h1"],"parties":["p2"],"road":"ashfen~carrbridge","road_rec":"r342"},{"id":"e1710","day":43,"season":2,"sday":13,"kind":"talent","imp":2,"text":"A Carrbridge landlord asks Juniper to bless the new barrel. Business picks up at once. Juniper puts it down to Weddings and Wakes.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"weddings_and_wakes"},{"id":"e1713","day":43,"season":2,"sday":13,"kind":"ability","imp":2,"text":"A Carrbridge couple who married forty years ago want to do it all again. Juniper obliges. 45 silver, a good cry, and a ration from the feast.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"weddings_and_wakes","sk":"Weddings and Wakes","rule":true},{"id":"e1772","day":45,"season":2,"sday":15,"kind":"hunt","imp":2,"text":"The King's Road: Juniper takes half of the berries and leaves half for whatever comes next, the way the old hunters always did.","heroes":["h10","h1"],"parties":["p2"],"loc":"kingsroad","road_rec":"r365"},{"id":"e1800","day":46,"season":2,"sday":16,"kind":"fight","imp":1,"text":"With Brix hitting hardest, the Vigil of Carrbridge defeats a Bandit on the King's Road. Brix kept them off everyone with Patient Shot. Loot: 6 silver each.","heroes":["h10","h1"],"parties":["p2"],"loc":"kingsroad","fight":"f103","foes":["bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"hero","reworded":-27},{"id":"e1807","day":46,"season":2,"sday":16,"kind":"campfire","imp":2,"text":"Juniper and Brix invent a scoring system for snoring. Nobody else is consulted.","heroes":["h10","h1"],"parties":["p2"],"loc":"kingsroad"},{"id":"e1821","day":47,"season":2,"sday":17,"kind":"fight","imp":1,"text":"The Vigil of Carrbridge sees off a Bandit Archer and a Bandit on the King's Road without much fuss. Brix closed it out with Aimed Shot on the bandit archer. Loot: 20 silver each, 1 bag of stolen goods.","heroes":["h10","h1"],"parties":["p2"],"loc":"kingsroad","fight":"f105","foes":["bandit_archer","bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e1834","day":47,"season":2,"sday":17,"kind":"music","imp":3,"text":"A crew anthem is born. The Vigil of Carrbridge have sung \"Dear Yeti Society\" so often, and so warmly, that last night it simply became theirs.","heroes":["h10","h1"],"parties":["p2"],"loc":"kingsroad","anthem":"dear_yeti_society","night":"n116"},{"id":"e1854","day":48,"season":2,"sday":18,"kind":"road","imp":3,"text":"A beggar on the King's Road hums a tune that Brix and Juniper both seem to know without knowing how. They finish it together, and the beggar is gone.","heroes":["h1","h10"],"parties":["p2"],"road":"carrbridge~kingsroad","road_rec":"r380"},{"id":"e1863","day":48,"season":2,"sday":18,"kind":"talent","imp":2,"text":"A Carrbridge baker comes up after Juniper's sermon and presses a loaf into her hands without a word. Sermon, cast gently, for once.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"sermon"},{"id":"e1909","day":49,"season":2,"sday":19,"kind":"campfire","imp":1,"text":"Brix walks the dark side of the road so Juniper doesn't have to, and never says why.","heroes":["h1","h10"],"parties":["p2"],"loc":"bleakmarsh"},{"id":"e1913","day":49,"season":2,"sday":19,"kind":"goal_progress","imp":2,"text":"The Vigil of Carrbridge is getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h10","h1"],"parties":["p2"]},{"id":"e1955","day":51,"season":2,"sday":21,"kind":"delve","imp":1,"text":"The Vigil of Carrbridge descends into Thornmere Ruins, mostly explored (88%), map in hand.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1956","day":51,"season":2,"sday":21,"kind":"fight","imp":2,"text":"In the pond banks on the second floor of Thornmere Ruins, the Vigil of Carrbridge squares up to 4 Bog Crawlers and carries the day. Brix's Headshot went in deep, and the bog crawler slowed down after that. Loot: 11 chitin, 2 bog crawler claws.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f115","foes":["bog_crawler","bog_crawler","bog_crawler"],"where":"in the pond banks on the second floor of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-25,"wx":"rain"},{"id":"e1957","day":51,"season":2,"sday":21,"kind":"delve_day","imp":1,"text":"The Vigil of Carrbridge tallies up the second floor of Thornmere Ruins at nightfall: two rooms, taken without hurrying, and the names go in the book (the pipe organ, the pond banks).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":1,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1998","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The map of Thornmere Ruins grows by two rooms of the second floor, walked at a steady pace by The Vigil of Carrbridge: the reed maze, the reed-choked treasury.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2019","day":53,"season":2,"sday":23,"kind":"delve_day","imp":1,"text":"By lamplight on the second floor of Thornmere Ruins, The Vigil of Carrbridge clears the way through two rooms, at a cautious pace: the sunken stair, the singing sump.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":2,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2030","day":53,"season":2,"sday":23,"kind":"campfire","imp":3,"text":"Juniper and Brix share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e2062","day":54,"season":2,"sday":24,"kind":"delve_day","imp":1,"text":"The cloister walk, the singing chapel, the gallery of charms and 1 more: the day's work on the deepest floor of Thornmere Ruins for The Vigil of Carrbridge, taken with a look round every corner.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":4,"empty":4,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e2099","day":55,"season":2,"sday":25,"kind":"delve_day","imp":1,"text":"It's the deepest floor of Thornmere Ruins today, and The Vigil of Carrbridge works through it steadily: six rooms (the drowned crypt, the pond banks, the undercroft arches and 3 more).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":6,"empty":5,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"rain"},{"id":"e2122","day":56,"season":2,"sday":26,"kind":"party_life","imp":3,"text":"At the top of the stair to the third floor, Juniper stopped and would not be moved, so The Vigil of Carrbridge turns for the surface and a late breakfast.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","refusal":"h10","wx":"rain"},{"id":"e2123","day":56,"season":2,"sday":26,"kind":"delve_done","imp":3,"text":"Thornmere Ruins hands The Vigil of Carrbridge back after 6 days, dusty and squinting. They got all the way to the bottom, cleared 7 rooms, found the pipe organ, the reed-choked treasury and a walled-up room beside the chapel of the first abbot, inked 91% of the map, came away with 184 silver between them and turned back when one of them would go no further. Pin it to the board: Thornmere Ruins is picked clean (98%).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","days":6,"bottom":true,"rooms":["the pipe organ","the reed-choked treasury"],"gold":184,"turn":"refused","wx":"rain"},{"id":"e2124","day":56,"season":2,"sday":26,"kind":"ambush","imp":3,"text":"The Vigil of Carrbridge wakes to a Will-o'-Wisp and a Bog Crawler in camp outside Thornmere Ruins in the middle of the night, and defeats them. The last bog crawler takes off and isn't seen again. Patient Shot did more for this fight than the scoreboard shows. That was Brix. Loot: 2 bottled wisplight.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f126","foes":["wisp","bog_crawler"],"where":"at their camp outside Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-37,"wx":"rain"},{"id":"e2168","day":57,"season":2,"sday":27,"kind":"road","imp":4,"text":"A dragon crosses the sky above the road to Bleakmarsh, so large that the day goes dark for a count of ten. Every beast and every traveller on the road falls flat. Juniper looks up.","heroes":["h10","h1"],"parties":["p2"],"road":"bleakmarsh~thornmere_ruins","road_rec":"r458"},{"id":"e2177","day":57,"season":2,"sday":27,"kind":"talent","imp":1,"text":"Brix picks a goose feather off the road and studies it like a jeweller. It goes in her hat for later.","heroes":["h1"],"parties":["p2"],"loc":"bleakmarsh","skill":"fletcher"},{"id":"e2221","day":58,"season":2,"sday":28,"kind":"campfire","imp":1,"text":"Juniper orders Brix a cheap swill before Brix even sits down. Remembering an order is how it starts.","heroes":["h1","h10"],"parties":["p2"],"loc":"ashfen","wx":"fog"},{"id":"e2289","day":60,"season":2,"sday":30,"kind":"goal_done","imp":4,"text":"The Vigil of Carrbridge can cross it off: see the world: 6 different places before the season ends. Drinks are on them. It was Juniper's idea in the first place. XP: Juniper +960 (level 17!), Brix +960 (level 17!).","heroes":["h10","h1"],"parties":["p2"],"xp":{"h10":960,"h1":960}},{"id":"e2325","day":61,"season":3,"sday":1,"kind":"wagon","imp":3,"text":"The Vigil of Carrbridge rolls out of Hollowood in a donkey cart called Grand Duchess, 29 silver between them. Who paid: Brix 20, Juniper 9.","heroes":["h10","h1"],"parties":["p2"],"loc":"hollowood"},{"id":"e2326","day":61,"season":3,"sday":1,"kind":"road","imp":2,"text":"The charcoal burners tell Brix where the old logging road meets the Sunken Vault, and warn her off it. They tell it with some relish.","heroes":["h1","h10"],"parties":["p2"],"road":"greenwood~hollowood","road_rec":"r484"},{"id":"e2391","day":62,"season":3,"sday":2,"kind":"fight","imp":1,"text":"It's a Tusked Boar against the Vigil of Carrbridge in the Greenwood, and it isn't close. The final blow was Brix's Follow My Arrow. Brix's Patient Shot picked its moment well. Loot: 1 pelt, 5 rations.","heroes":["h10","h1"],"parties":["p2"],"loc":"greenwood","fight":"f137","foes":["boar"],"where":"in The Greenwood","won":true,"close":false,"shape":"foe","reworded":-13},{"id":"e2392","day":62,"season":3,"sday":2,"kind":"night","imp":2,"text":"Something sings in the dark in the Greenwood. Juniper goes to look and comes back with a trinket and a very quiet manner.","heroes":["h10","h1"],"parties":["p2"],"loc":"greenwood"},{"id":"e2408","day":63,"season":3,"sday":3,"kind":"fight","imp":2,"text":"Back in the Greenwood, the Vigil of Carrbridge beats 3 Wolves. The last wolf slips away while nobody is looking. Brix's Headshot found the wolf from the back row. Ask the others what won it: Brix's Patient Shot. Loot: 2 pelts.","heroes":["h10","h1"],"parties":["p2"],"loc":"greenwood","fight":"f139","foes":["wolf","wolf","wolf"],"where":"in The Greenwood","won":true,"close":false,"shape":"again","reworded":-35},{"id":"e2415","day":63,"season":3,"sday":3,"kind":"talent","imp":2,"text":"The crew walks behind Juniper's pack and smells faintly of ham. Brix has stopped complaining. Chalk it up to Smokehouse.","heroes":["h10","h1"],"parties":["p2"],"loc":"greenwood","skill":"smokehouse"},{"id":"e2435","day":64,"season":3,"sday":4,"kind":"road","imp":2,"text":"Juniper pays the honey tax, one copper in a tin. The hermit takes it with great seriousness and gives back a dripping slab of comb as change.","heroes":["h10","h1"],"parties":["p2"],"road":"greenwood~thornwall","road_rec":"r522"},{"id":"e2447","day":64,"season":3,"sday":4,"kind":"ability","imp":2,"text":"A Thornwall family asks Juniper to say the words at Grandad's wake. She makes everyone laugh twice. 29 silver and a ration of funeral ham.","heroes":["h10"],"parties":["p2"],"loc":"thornwall","skill":"weddings_and_wakes","sk":"Weddings and Wakes","rule":true,"wx":"fog"},{"id":"e2516","day":66,"season":3,"sday":6,"kind":"campfire","imp":1,"text":"Pepper the dog won't sleep unless Juniper is in sight. Nobody can explain it.","heroes":["h1","h10"],"parties":["p2"],"loc":"carrbridge"},{"id":"e2531","day":67,"season":3,"sday":7,"kind":"road","imp":4,"text":"The Fourth-Best Company ask to join Brix. Brix declines, politely. Captain Mabb says they'll be fourth-best on their own terms, then.","heroes":["h1","h10"],"parties":["p2"],"road":"ashfen~carrbridge","traveller":"fourth_best","road_rec":"r538"},{"id":"e2542","day":67,"season":3,"sday":7,"kind":"talent","imp":2,"text":"Three Ashfen couples ask Juniper to bless their engagement on the same afternoon. She does it in bulk.","heroes":["h10"],"parties":["p2"],"loc":"ashfen","skill":"weddings_and_wakes"},{"id":"e2611","day":69,"season":3,"sday":9,"kind":"ability","imp":2,"text":"Juniper blesses the first loaf from a new Carrbridge bakery. 34 silver, and the baker presses a ration on her as well, with a wink.","heroes":["h10"],"parties":["p2"],"loc":"carrbridge","skill":"weddings_and_wakes","sk":"Weddings and Wakes","rule":true},{"id":"e2619","day":70,"season":3,"sday":10,"kind":"ambush","imp":2,"text":"With Juniper taking the worst of it, the Vigil of Carrbridge defeats a Bandit Captain and a Bandit on the caravan road, guarding wagons of rope. Brix landed Patient Shot on the bandit hard enough to hear from the back. Juniper's Spellsong was the quiet reason it went their way. Loot: 35 silver each, 6 stolen goods, 1 gem.","heroes":["h10","h1"],"parties":["p2"],"loc":"kingsroad","fight":"f158","foes":["bandit_captain","bandit"],"where":"on the caravan road, guarding wagons of rope","won":true,"close":false,"shape":"hero","reworded":-37},{"id":"e2620","day":70,"season":3,"sday":10,"kind":"caravan","imp":3,"text":"The Vigil of Carrbridge brings a caravan of rope safely into Carrbridge despite an ambush on the road. The guild pays 75 silver and promises more work.","heroes":["h10","h1"],"parties":["p2"],"loc":"carrbridge"},{"id":"e2638","day":70,"season":3,"sday":10,"kind":"contract","imp":2,"text":"The Vigil of Carrbridge takes down the poster in Carrbridge: Gnasher is hers. Or will be.","heroes":["h10","h1"],"parties":["p2"],"loc":"carrbridge"},{"id":"e2676","day":71,"season":3,"sday":11,"kind":"night","imp":2,"text":"Something small and clever gets into The Vigil of Carrbridge's camp in Redcrag Hills overnight. Juniper wakes up 9 silver and 3 rations lighter.","heroes":["h10","h1"],"parties":["p2"],"loc":"redcrag"},{"id":"e2698","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Vigil of Carrbridge settles on a goal: to finish the season as one of the top three parties.","heroes":["h10","h1"],"parties":["p2"]},{"id":"e2741","day":72,"season":3,"sday":12,"kind":"campfire","imp":2,"text":"Juniper and Brix spend an evening at the campfire trying to whistle through a blade of grass. Only Brix manages.","heroes":["h10","h1"],"parties":["p2"],"loc":"redcrag"},{"id":"e2746","day":72,"season":3,"sday":12,"kind":"contract","imp":2,"text":"The Carrbridge guild calls off the bounty on Gnasher before The Vigil of Carrbridge can find it. Days of tracking, for a story.","heroes":["h10","h1"],"parties":["p2"],"loc":"carrbridge"},{"id":"e2783","day":73,"season":3,"sday":13,"kind":"campfire","imp":1,"text":"Brix patches Juniper's cloak without being asked. Juniper pretends not to notice, then says thanks.","heroes":["h10","h1"],"parties":["p2"],"loc":"redcrag"},{"id":"e2823","day":74,"season":3,"sday":14,"kind":"map_shared","imp":1,"text":"Maps change hands in Redcrag Hills: Gilded Wall gives The Vigil of Carrbridge a copy of what they know of the Sunken Vault, as far as the first floor.","heroes":["h9","h6","h10","h1"],"parties":["p6","p2"],"loc":"redcrag","dungeon":"sunken_vault","price":0},{"id":"e2824","day":74,"season":3,"sday":14,"kind":"meet","imp":1,"text":"Gilded Wall and The Vigil of Carrbridge share a fire in Redcrag Hills. There is a short argument about the best road to Ironhaven.","heroes":["h9","h6","h10","h1"],"parties":["p6","p2"],"loc":"redcrag"},{"id":"e2863","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Brix shoots a falling leaf in half, then pretends it was an accident. Nobody believes her. Follow My Arrow all the way, Brix insists.","heroes":["h1"],"parties":["p2"],"loc":"redcrag","skill":"follow_my_arrow"},{"id":"e2879","day":76,"season":3,"sday":16,"kind":"road","imp":3,"text":"Sir Aldous Puddle and Juniper spar on the bridge for an hour. He marks the result on the board, and the horse watches without interest.","heroes":["h10","h1"],"parties":["p2"],"road":"ironhaven~redcrag","traveller":"aldous","road_rec":"r607"},{"id":"e2900","day":76,"season":3,"sday":16,"kind":"ability","imp":2,"text":"Juniper blesses a new mill in Ironhaven, a goat and a very nervous baby, all before lunch. 23 silver, and a ration for the road.","heroes":["h10"],"parties":["p2"],"loc":"ironhaven","skill":"weddings_and_wakes","sk":"Weddings and Wakes","rule":true,"wx":"rain"},{"id":"e2944","day":78,"season":3,"sday":18,"kind":"road","imp":2,"text":"Brix passes the Wet Boots Angling Club for the first time, who have all taken their boots off and set them in a row to dry like trophies.","heroes":["h1","h10"],"parties":["p2"],"road":"bleakmarsh~carrbridge","traveller":"wet_boots","road_rec":"r629"},{"id":"e2957","day":78,"season":3,"sday":18,"kind":"meet","imp":1,"text":"The Sunlit Almanac and The Vigil of Carrbridge share a fire in Bleakmarsh and split the last of somebody's bread. The news goes round twice.","heroes":["h8","h20","h18","h19","h10","h1"],"parties":["p4","p2"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2958","day":78,"season":3,"sday":18,"kind":"talent","imp":2,"text":"Brix spots feverfew in a ditch near Bleakmarsh and bags it before anyone else notices. Forager: a ranger's patience, mostly.","heroes":["h1"],"parties":["p2"],"loc":"bleakmarsh","skill":"forager","wx":"storm"},{"id":"e2993","day":79,"season":3,"sday":19,"kind":"road","imp":2,"text":"Juniper comes upon the Kettleby Tinkers for the first time eating Wild Onion Broth out of a hat, because the bowls are all being mended.","heroes":["h10","h1"],"parties":["p2"],"road":"bleakmarsh~thornmere_ruins","traveller":"kettleby","road_rec":"r642"},{"id":"e2999","day":79,"season":3,"sday":19,"kind":"map_shared","imp":1,"text":"The Vigil of Carrbridge leaves the fire at the mouth of Thornmere Ruins with a copy of the map of the Ashveil Crypts, drawn out by Verdant Edge as far as the second floor and signed with a flourish.","heroes":["h12","h17","h10","h1"],"parties":["p8","p2"],"loc":"thornmere_ruins","dungeon":"ashveil_crypts","price":0,"wx":"storm"},{"id":"e3000","day":79,"season":3,"sday":19,"kind":"meet","imp":1,"text":"Verdant Edge and The Vigil of Carrbridge share a fire at the mouth of Thornmere Ruins and trade news.","heroes":["h12","h17","h10","h1"],"parties":["p8","p2"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e3016","day":80,"season":3,"sday":20,"kind":"delve","imp":1,"text":"The Vigil of Carrbridge descends into Thornmere Ruins, partly explored (51%), map in hand.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e3017","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"Thornmere Ruins, the second floor: six rooms for The Vigil of Carrbridge, at full stretch. On the map now: The Lantern That Waits, the reliquary niche, the curtain of hair and 3 more.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":6,"empty":6,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e3072","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"The deepest floor of Thornmere Ruins, taken at speed: The Vigil of Carrbridge gets through five rooms (a trapdoor in the vestry floor, black water lapping under it, the black pool, the brewhouse and 2 more).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":5,"empty":5,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e3073","day":81,"season":3,"sday":21,"kind":"talent","imp":2,"text":"Juniper makes Brix stop walking on a twisted ankle. Brix complains, sits down, and is better by morning. Somebody asks how. 'Medic,' says Juniper.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","skill":"medic","wx":"fog"},{"id":"e3077","day":81,"season":3,"sday":21,"kind":"gift","imp":2,"text":"Juniper admired Brix's Third-Place Ribbon one too many times. Now it's Juniper's.","heroes":["h1","h10"],"parties":["p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e3095","day":82,"season":3,"sday":22,"kind":"delve_day","imp":1,"text":"The Vigil of Carrbridge keeps at the deepest floor of Thornmere Ruins carefully, two rooms deep in the day: the abbot's lodging, the reliquary niche.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e3117","day":82,"season":3,"sday":22,"kind":"map_shared","imp":1,"text":"Red Hammers charge The Vigil of Carrbridge 6 silver to copy the map of the Ashveil Crypts. It's a fair price for a good map.","heroes":["h13","h14","h10","h1"],"parties":["p1","p2"],"loc":"thornmere_ruins","dungeon":"ashveil_crypts","price":6,"wx":"fog"},{"id":"e3118","day":82,"season":3,"sday":22,"kind":"meet","imp":1,"text":"Red Hammers and The Vigil of Carrbridge share a fire in Thornmere Ruins. There is a short argument about the best road to Thornwall.","heroes":["h13","h14","h10","h1"],"parties":["p1","p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e3134","day":83,"season":3,"sday":23,"kind":"delve_day","imp":1,"text":"The map of Thornmere Ruins grows by five rooms of the deepest floor, walked at a steady pace by The Vigil of Carrbridge: the physic garden, a sealed space off the physic garden, the cloister walk and 2 more.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":5,"empty":4,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e3179","day":84,"season":3,"sday":24,"kind":"delve_day","imp":1,"text":"Deeper into the deepest floor of Thornmere Ruins: The Vigil of Carrbridge sees two rooms today, one door at a time (the lamp-lit passage, the hag's still room).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e3180","day":84,"season":3,"sday":24,"kind":"talent","imp":1,"text":"Juniper writes a letter home in squid ink by the fire. By morning the letter smells of the sea.","heroes":["h10"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e3181","day":84,"season":3,"sday":24,"kind":"night","imp":3,"text":"Juniper follows strange lights away from the camp on the deepest floor of Thornmere Ruins, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e3200","day":84,"season":3,"sday":24,"kind":"campfire","imp":1,"text":"Brix tells Juniper something they've never told anyone. Juniper keeps it.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e3210","day":85,"season":3,"sday":25,"kind":"fight","imp":1,"text":"The Vigil of Carrbridge runs into 2 Sirens in the choir loft on the deepest floor of Thornmere Ruins and comes out on top. Brix's Headshot found the siren from the back row. Loot: 3 sea grapes.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f180","foes":["siren","siren"],"where":"in the choir loft on the deepest floor of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-23},{"id":"e3211","day":85,"season":3,"sday":25,"kind":"delve_day","imp":1,"text":"It's the deepest floor of Thornmere Ruins today, and The Vigil of Carrbridge works through it with a look round every corner: two rooms (the choir loft, the hag's still room).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e3255","day":86,"season":3,"sday":26,"kind":"boss","imp":5,"text":"Mother Thornmere's Brood and a Drake have held the bottom of Thornmere Ruins long enough: the Vigil of Carrbridge finishes them off. Brix's last Aimed Shot settled it. Bless, from Juniper, at exactly the right moment. Brix and Pepper the dog found the way out together. Loot: 258 silver each, 13 moonpetal, 9 bottled wisplight.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f184","foes":["hag_mother","drake"],"where":"at the bottom of Thornmere Ruins","won":true,"close":true,"shape":"foe","reworded":-32},{"id":"e3256","day":86,"season":3,"sday":26,"kind":"treasure","imp":2,"text":"Mother Thornmere's Brood is dead and the hoard is unguarded: 18 gold pieces and 8 silver, and nobody left to object.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","in_fight":"f184"},{"id":"e3257","day":86,"season":3,"sday":26,"kind":"sniped","imp":3,"text":"On the road to Thornmere Ruins, Red Hammers hear that The Vigil of Carrbridge killed Mother Thornmere's Brood today. Red Hammers go on anyway: the place is still mostly explored (68%), and there's more down there than one boss.","heroes":["h13","h14","h10","h1"],"parties":["p1","p2"],"loc":"thornmere_ruins","snipers":["h10","h1"],"where":"road","boss":"Mother Thornmere's Brood","in_fight":"f184"},{"id":"e3258","day":86,"season":3,"sday":26,"kind":"race_won","imp":1,"text":"The Vigil of Carrbridge wins the race to Mother Thornmere's Brood, ahead of Red Hammers. The bets are paid out in Carrbridge before the blood is dry.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","in_fight":"f184"},{"id":"e3259","day":86,"season":3,"sday":26,"kind":"gear","imp":1,"text":"In the Hag Mother's nest on the deepest floor of Thornmere Ruins, Brix finds Delver's Ridgewalker Boots and puts them on. Delver's: harder to ambush (+8%).","heroes":["h1"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e3260","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Vigil of Carrbridge tallies up the deepest floor of Thornmere Ruins at nightfall: one room, taken without hurrying, and the names go in the book (the Hag Mother's nest).","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":1,"empty":0,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":0,"wild":[]}},{"id":"e3261","day":86,"season":3,"sday":26,"kind":"delve_done","imp":3,"text":"Thornmere Ruins hands The Vigil of Carrbridge back after 7 days, dusty and squinting. They found the reliquary niche, the lantern rack, the hag's still room and 1 more good room, went as deep as the place goes, inked 86% of the map, took 8 rooms off the map's blank side and split 1100 silver on the way up. Thornmere Ruins is mostly explored (70%), going by everyone's notes.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins","days":7,"bottom":true,"rooms":["the reliquary niche","the lantern rack"],"gold":1100,"turn":"done"},{"id":"e3274","day":86,"season":3,"sday":26,"kind":"campfire","imp":1,"text":"Juniper and Brix reach a truce over the good blanket: alternate nights, strictly kept, frequently cheated.","heroes":["h10","h1"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e3278","day":86,"season":3,"sday":26,"kind":"big_move","imp":4,"text":"Mother Thornmere's Brood and a Drake have held the bottom of Thornmere Ruins long enough: the Vigil of Carrbridge finishes them off. On the table: Brix +99 renown (14th to 1st) and Juniper +97 (19th to 3rd). The Vigil of Carrbridge +139 party renown (8th to 1st among the crews).","heroes":["h1","h10"],"parties":["p2"],"cause":"e3255","moves":[{"hero":"h1","gain":99,"from":14,"to":1},{"hero":"h10","gain":97,"from":19,"to":3}],"party_moves":[{"party":"p2","gain":139,"from":8,"to":1}],"fight":"f184"},{"id":"e3387","day":89,"season":3,"sday":29,"kind":"campfire","imp":2,"text":"Brix and Juniper start a running tally of who saved whom. It is currently tied, and disputed.","heroes":["h1","h10"],"parties":["p2"],"loc":"bleakmarsh","wx":"rain"},{"id":"e3433","day":90,"season":3,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Vigil of Carrbridge set out to finish the season as one of the top three parties, and the final table says they made it. XP: Juniper +800 (level 20!), Brix +800 (level 20!).","heroes":[],"parties":["p2"],"xp":{"h10":800,"h1":800}},{"id":"e3439","day":90,"season":3,"sday":30,"kind":"season_end","imp":5,"text":"Season 3 ends. Brix is Hero of the Season with 286 renown. The Vigil of Carrbridge finishes as the top party.","heroes":["h1","h10"],"parties":["p2"]},{"id":"e3440","day":90,"season":3,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Vigil of Carrbridge (Juniper and Brix) ends season 3 as the league's best crew, 289 party renown. Their season: 1 boss, 5 fights won and 3 floors explored.","heroes":["h10","h1"],"parties":["p2"]},{"id":"e3449","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Vigil of Carrbridge, to keep the peace: never draw first on another hero (sworn in season 2); The Amber Sigil, never to retreat (sworn in season 2); The Sunlit Almanac, to keep the peace: never draw first on another hero (sworn in season 2); The Scarlet Gallopers, that no one leaves this party (sworn in season 2); Gilded Wall, never to leave a companion behind (sworn in season 2); Verdant Edge, to share every coin (sworn in season 2); Duren, never to pay a toll (sworn in season 1). Every one of them held.","heroes":["h3"],"parties":["p2","p3","p4","p5","p6","p8"]}],"roles":{"h10":"Leader · Healer","h1":"Blade"},"quest":{"what":"Hunt","where":"Bleakmarsh","why":"Brix wants to be out after game","floor":null,"floors":null},"tactics":{"front":[],"back":["h10","h1"],"plan":"Juniper casts from behind; Brix picks off whatever gets close; Juniper keeps everyone standing.","traits":{"boldness":0.56,"risk":0.04,"greed":-0.31,"sociability":0.4,"honor":0.77,"curiosity":-0.02,"temper":-0.3,"loyalty":-0.23},"mix":"1 caster, 1 bow","notes":["Nobody wants the front row. Whoever's nearest takes the hits."],"style":["bold","mixed"],"skills":[{"label":"Damage","skills":[{"hero":"h1","id":"headshot","name":"Headshot","desc":"Between the eyes.","tags":["crit"],"rank":2,"uses":12},{"hero":"h1","id":"aimed_shot","name":"Aimed Shot","desc":"Breathes out. Lets go.","tags":["crit","hunt"],"rank":1,"uses":6},{"hero":"h10","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":1,"uses":4},{"hero":"h10","id":"radiance","name":"Radiance","desc":"A flash of holy light, right in the eyes.","tags":["holy"],"rank":1,"uses":1},{"hero":"h1","id":"quick_shot","name":"Quick Shot","desc":"Two arrows before the first lands.","tags":["hunt"],"rank":1,"uses":0}]},{"label":"Healing","skills":[{"hero":"h10","id":"miracle","name":"Miracle","desc":"Witnesses still argue about what they saw.","tags":["holy","heal"],"rank":1,"uses":0}]},{"label":"Defence","skills":[{"hero":"h10","id":"spellsong","name":"Spellsong","desc":"Hums a tune that makes swords sharper.","tags":["music","arcane"],"rank":1,"uses":9},{"hero":"h10","id":"bless","name":"Bless","desc":"Gods go with you. Hit harder.","tags":["holy"],"rank":2,"uses":8}]},{"label":"Tricks","skills":[{"hero":"h1","id":"patient_shot","name":"Patient Shot","desc":"Has had the shot lined up since breakfast.","tags":["crit"],"rank":3,"uses":13},{"hero":"h1","id":"follow_my_arrow","name":"Follow My Arrow","desc":"Shows you the gap in the armour. With an arrow. Then you hit it too.","tags":[],"rank":1,"uses":5},{"hero":"h10","id":"second_chance","name":"Second Chance","desc":"The gods allow one do-over per fight.","tags":["heal","holy"],"rank":1,"uses":0},{"hero":"h10","id":"home_fires","name":"Home Fires","desc":"Thinks of home and digs in.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"over_the_shoulder","name":"Over the Shoulder","desc":"Hurt, falls back at a run, and shoots without looking round.","tags":["travel","crit"],"rank":1,"uses":0},{"hero":"h1","id":"bane_of_bosses","name":"Bane of Bosses","desc":"The bigger the crown, the louder it falls.","tags":[],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h10","id":"toughness","name":"Toughness","desc":"Built like a barn door.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"shoulder_to_shoulder","name":"Shoulder to Shoulder","desc":"Stands close enough to share a shield.","tags":["command"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h10","id":"sermon","name":"Sermon","desc":"Preaches on market day. Alms, standing, the odd convert.","tags":["holy"],"rank":2,"uses":0},{"hero":"h10","id":"toll_talker","name":"Toll Talker","desc":"Has never paid a full toll. Has never been rude about it.","tags":["travel","trade"],"rank":1,"uses":0},{"hero":"h10","id":"medic","name":"Medic","desc":"Injuries heal faster in their party.","tags":["heal"],"rank":1,"uses":0},{"hero":"h10","id":"last_rites","name":"Last Rites","desc":"Says the words over the fallen. The crew sleeps better.","tags":["holy"],"rank":3,"uses":0},{"hero":"h10","id":"smokehouse","name":"Smokehouse","desc":"Smoked fish, smoked sausage, smoked everything.","tags":[],"rank":1,"uses":0},{"hero":"h10","id":"supply_master","name":"Supply Master","desc":"Gets supplies at cost.","tags":["trade"],"rank":1,"uses":0},{"hero":"h10","id":"tea_ceremony","name":"Tea Ceremony","desc":"Nothing is so bad it can't wait for the kettle.","tags":[],"rank":1,"uses":0},{"hero":"h10","id":"hymn_singer","name":"Hymn Singer","desc":"Sings the old hymns in a voice like a warm bath.","tags":["holy","music"],"rank":1,"uses":0},{"hero":"h1","id":"fencing_lessons","name":"Fencing Lessons","desc":"Teaches the basics. Charges for the advanced.","tags":["crit"],"rank":1,"uses":0},{"hero":"h1","id":"weather_eye","name":"Weather Eye","desc":"Smells rain two hours off.","tags":["storm"],"rank":1,"uses":0},{"hero":"h1","id":"trick_shot","name":"Trick Shot","desc":"Shoots the apple off your head. Asks first.","tags":["crit"],"rank":3,"uses":0},{"hero":"h1","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":2,"uses":0},{"hero":"h1","id":"angler","name":"Angler","desc":"Has a line in the water before the tent is up.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"horse_whisperer","name":"Horse Whisperer","desc":"Horses don't go lame on their watch, and thieves can't lead one off.","tags":["ride","beast"],"rank":1,"uses":0},{"hero":"h1","id":"fletcher","name":"Fletcher","desc":"Every arrow straight, every feather matched.","tags":["craft","crit"],"rank":1,"uses":0},{"hero":"h1","id":"smokehouse","name":"Smokehouse","desc":"Smoked fish, smoked sausage, smoked everything.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h10","dmg":210,"healed":0,"taken":204,"kills":2,"row":"back"},{"hero":"h1","dmg":1776,"healed":0,"taken":36,"kills":8,"row":"back"}],"ground":{"name":"Thornmere Ruins","fights":4}},"trophies":[{"boss":"Mother Thornmere's Brood","monster":"hag_mother","place":"Thornmere Ruins","day":86,"season":3,"fight":"f184"}]};